def main():
    assert len(PREDS) == 20, len(PREDS)
    ids = [p["case_id"] for p in PREDS]
    assert ids == EXPECTED, ids
    assert len(set(ids)) == 20
    OUT.mkdir(parents=True, exist_ok=True)
    for p in PREDS:
        assert set(p.keys()) == {"case_id","prediction_text","basis","confidence","trigger"}, p["case_id"]
        assert 0.0 <= p["confidence"] <= 1.0
        t = p["trigger"]
        assert set(t.keys()) == {"changed_main","reserve_used","disputed","reason"}
        if not p["case_id"].startswith("DT-"):
            assert t == {"changed_main": False, "reserve_used": False, "disputed": False, "reason": ""}, p["case_id"]
        (OUT / f"{p['case_id']}.json").write_text(
            json.dumps(p, ensure_ascii=False, indent=2), encoding="utf-8")
    print("WROTE", len(PREDS))

if __name__ == "__main__":
    main()
